export function PermissionSelector({
  user = "{{user}}",
  scope = "{{scope}}",
  role = "{{role}}",
  inherited = {{inherited}},
  color = "{{color}}",
}) {
  const badge = {
    viewer: { background: "transparent", color: "#241430", borderColor: color },
    editor: { background: color, color: "#241430", borderColor: color },
    admin: { background: "#241430", color: "#FAF7F2", borderColor: "#241430" },
    owner: { background: "#E8A020", color: "#241430", borderColor: "#E8A020" },
  }[role] ?? {};
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap", font: "14px/1.4 system-ui, sans-serif", color: "#241430", maxWidth: 360 }}>
      <div>
        <strong style={{ display: "block" }}>{user}</strong>
        <span style={{ display: "block", fontSize: 12, opacity: 0.75 }}>{scope}{inherited ? " · Inherited" : ""}</span>
      </div>
      <label style={{ display: "flex", flexDirection: "column", fontSize: 12, gap: 2, marginLeft: "auto" }}>
        <span>Permission</span>
        <select defaultValue={role} style={{ border: `1.5px solid ${color}`, borderRadius: 8, padding: "5px 8px", background: "#FAF7F2", color: "#241430" }}>
          <option value="viewer">Can view</option>
          <option value="editor">Can edit</option>
          <option value="admin">Can administer</option>
          <option value="owner">Owns resource</option>
        </select>
      </label>
      <span style={{ fontSize: 11, fontWeight: 700, textTransform: "uppercase", padding: "3px 8px", borderRadius: 999, border: "1.5px solid", ...badge }}>{role}</span>
    </div>
  );
}
